import "core-js/modules/es6.function.name";
import "core-js/modules/es6.regexp.replace";
import "core-js/modules/es6.regexp.to-string";
import { putFile } from "@/api/assets/ageConfigureManage";
import website from '@/config/website';
import { Base64 } from 'js-base64';
import { getToken } from '@/util/auth';
export default {
  props: ['isShow'],
  data: function data() {
    return {
      // isVisible: false,
      title: '请导入数据文件',
      headers: {
        Authorization: "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret))),
        'Idevelop-Auth': 'bearer ' + getToken()
      },
      datas: {},
      url: '#',
      isUploading: false,
      fileList: [],
      // [{name: 'name', url: 'url'}]
      activeIcon: '',
      uploading: false
    };
  },
  computed: {
    isVisible: {
      get: function get() {
        return this.isShow;
      },
      set: function set(val) {
        this.$emit("update:isShow", val);
      }
    }
  },
  mounted: function mounted() {
    // this.url = '/api/idevelop-device/device/storage/info/import'
    // this.url = '/api/idevelop-resource/oss/endpoint/put-file'
  },
  methods: {
    customUpload: function customUpload(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      putFile(formData).then(function (res) {
        params.onSuccess(res);
      }).catch(function (error) {
        params.onError(error);
      });
    },
    // 提交上传文件
    submitFileForm: function submitFileForm() {
      //判断有没有文件
      if (this.$refs.upload.uploadFiles.length == 0) {
        this.$alert("\u8BF7\u9009\u62E9\u8981\u4E0A\u4F20\u7684xlsx\u6587\u4EF6");
        return;
      }
      this.uploading = true;
      this.$refs.upload.submit();
    },
    //上传之前操作(用于判断是否重名与格式限制)
    beforeUpload: function beforeUpload(file) {
      // this.secure()
    },
    handleFileUploadProgress: function handleFileUploadProgress() {},
    handleSuccess: function handleSuccess(res) {
      // if( res.data.exceptionField ){
      //   this.$message.error(res.data.exceptionField)
      // }
      this.$emit('setVal', res.data);
      this.isVisible = false;
      this.uploading = false;
    },
    handleError: function handleError(err) {
      this.fileList = [];
      this.uploading = false;
      try {
        var myError = err.toString();
        myError = myError.replace('Error: ', '');
        myError = JSON.parse(myError);
        this.$message.error(myError.msg);
      } catch (err) {
        this.$message.error(err.toString());
      }
    },
    handlePreview: function handlePreview(file) {},
    handleRemove: function handleRemove(file, fileList) {},
    beforeRemove: function beforeRemove(file, fileList) {
      return this.$confirm("\u786E\u5B9A\u79FB\u9664 ".concat(file.name));
    },
    handleExceed: function handleExceed(file, fileList) {
      // this.$message.warning('')
    }
  }
};
